CREATE TRIGGER txns_insert_amounts BEFORE INSERT ON `txns` WHEN (NEW.`subtotal` IS NOT NULL AND (typeof(NEW.`subtotal`) != 'integer' OR abs(NEW.`subtotal`) > 9007199254740991)) OR (NEW.`discount` IS NOT NULL AND (typeof(NEW.`discount`) != 'integer' OR abs(NEW.`discount`) > 9007199254740991)) OR (NEW.`taxable` IS NOT NULL AND (typeof(NEW.`taxable`) != 'integer' OR abs(NEW.`taxable`) > 9007199254740991)) OR (NEW.`cgst` IS NOT NULL AND (typeof(NEW.`cgst`) != 'integer' OR abs(NEW.`cgst`) > 9007199254740991)) OR (NEW.`sgst` IS NOT NULL AND (typeof(NEW.`sgst`) != 'integer' OR abs(NEW.`sgst`) > 9007199254740991)) OR (NEW.`igst` IS NOT NULL AND (typeof(NEW.`igst`) != 'integer' OR abs(NEW.`igst`) > 9007199254740991)) OR (NEW.`cess` IS NOT NULL AND (typeof(NEW.`cess`) != 'integer' OR abs(NEW.`cess`) > 9007199254740991)) OR (NEW.`charges` IS NOT NULL AND (typeof(NEW.`charges`) != 'integer' OR abs(NEW.`charges`) > 9007199254740991)) OR (NEW.`round_off` IS NOT NULL AND (typeof(NEW.`round_off`) != 'integer' OR abs(NEW.`round_off`) > 9007199254740991)) OR (NEW.`total` IS NOT NULL AND (typeof(NEW.`total`) != 'integer' OR abs(NEW.`total`) > 9007199254740991)) OR typeof(NEW.number) != 'integer' OR NEW.number < 1 OR NEW.status NOT IN ('draft','posted','cancelled','open','closed','converted') BEGIN SELECT RAISE(ABORT,'Invalid amount or quantity'); END;
